package at.foama.wien;
import org.junit.*;import static org.junit.Assert.*;
import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.android.controller.ActivityController;
import org.json.*;import android.view.*;import android.widget.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.io.*;import java.net.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,qualifiers="w227dp-h227dp-round-xhdpi") @LooperMode(LooperMode.Mode.PAUSED)
public class TransferManagerTest {
 static class Connection extends HttpURLConnection {final String response;ByteArrayOutputStream sent=new ByteArrayOutputStream();boolean disconnected;Connection(URL u,String response){super(u);this.response=response;}public void connect(){}public void disconnect(){disconnected=true;}public boolean usingProxy(){return false;}public int getResponseCode(){return 200;}public OutputStream getOutputStream(){return sent;}public InputStream getInputStream(){return new ByteArrayInputStream(response.getBytes(StandardCharsets.UTF_8));}}
 @Test public void webCryptoCiphertextDecryptsOnWatchAndWatchCiphertextIsAvailableForCrossRuntimeCheck()throws Exception{
  JSONObject fixture=new JSONObject(new String(Files.readAllBytes(Paths.get("tests/fixtures/transfer-webcrypto.json")),StandardCharsets.UTF_8));TransferManager manager=new TransferManager(BuildConfig.FOAMA_BASE_URL);System.arraycopy(TransferManager.dec(fixture.getString("key")),0,manager.secret,0,32);
  assertEquals(fixture.getJSONObject("value").toString(),manager.decrypt(fixture.getJSONObject("packet")).toString());JSONObject result=new JSONObject().put("key",fixture.getString("key")).put("value",fixture.getJSONObject("value")).put("packet",manager.encrypt(fixture.getJSONObject("value")));Files.write(Paths.get(".local/transfer-java-packet.json"),result.toString().getBytes(StandardCharsets.UTF_8));
  JSONObject bad=fixture.getJSONObject("packet");byte[] bytes=TransferManager.dec(bad.getString("ciphertext"));bytes[0]^=1;bad.put("ciphertext",TransferManager.enc(bytes));try{manager.decrypt(bad);fail("Tampering accepted");}catch(javax.crypto.AEADBadTagException expected){}manager.destroy();for(byte b:manager.secret)assertEquals(0,b);
 }
 @Test public void qrCarriesSeparateCapabilitiesAndCreateDoesNotTransmitTheEncryptionKey()throws Exception{
  TransferManager m=new TransferManager(BuildConfig.FOAMA_BASE_URL);Connection[] last={null};RequestScope scope=new RequestScope(url->{last[0]=new Connection(url,"{\"expiresAt\":"+(System.currentTimeMillis()+600000)+"}");return last[0];});m.create(scope);String body=last[0].sent.toString("UTF-8");assertFalse(body.contains(TransferManager.enc(m.secret)));assertTrue(body.contains("readHash"));assertTrue(body.contains("journey-alternatives-v1"));assertFalse(last[0].getURL().toString().contains("key="));assertTrue(m.qrUrl().startsWith(BuildConfig.FOAMA_BASE_URL+"/transfer.html#"));assertTrue(m.qrUrl().contains("action=upload"));m.poll(scope);assertNotNull(last[0].getRequestProperty("X-Transfer-Secret"));assertTrue(last[0].disconnected);scope.cancel();try{m.poll(scope);fail("Cancelled transfer sent a request");}catch(java.io.InterruptedIOException expected){}
 }
 @Test public void nativeQrDecodesExactlyIncludingTheFragmentAndQuietZone()throws Exception{
  TransferManager manager=new TransferManager(BuildConfig.FOAMA_BASE_URL,"to-phone");android.graphics.Bitmap bitmap=MainActivity.qrBitmap(manager.qrUrl());int width=bitmap.getWidth();int[] pixels=new int[width*width];bitmap.getPixels(pixels,0,width,0,0,width,width);com.google.zxing.BinaryBitmap image=new com.google.zxing.BinaryBitmap(new com.google.zxing.common.HybridBinarizer(new com.google.zxing.RGBLuminanceSource(width,width,pixels)));assertEquals(manager.qrUrl(),new com.google.zxing.qrcode.QRCodeReader().decode(image).getText());bitmap.recycle();
 }
 @Test public void previewRejectsOtherFormatsSkipsUnknownsAndPreservesExistingOrder()throws Exception{
  Repo repo=new Repo(RuntimeEnvironment.getApplication());repo.favorites.clear();Repo.Stop stop=repo.stops.get(0);repo.toggleFavorite(stop,"46","A");JSONArray rows=new JSONArray().put(new JSONObject().put("stopId",stop.id).put("route","46").put("towards","A")).put(new JSONObject().put("stopId",stop.id).put("route","49").put("towards","B")).put(new JSONObject().put("stopId","missing")).put(new JSONObject().put("stopId",stop.id).put("route","49").put("towards","B"));
  TransferManager.Preview p=TransferManager.preview(new JSONObject().put("format","foama-favorites-v1").put("favorites",rows),repo);assertEquals(1,p.favorites.length());assertEquals(2,p.duplicates);assertEquals(1,p.unknown);assertEquals(1,repo.favorites.size());repo.mergeFavorites(p.favorites,false);assertEquals("46",repo.favorites.get(0).route);assertEquals("49",repo.favorites.get(1).route);
  try{TransferManager.preview(new JSONObject().put("format","other").put("favorites",rows),repo);fail("Wrong format accepted");}catch(IllegalArgumentException expected){}
 }
 @Test public void receivedFavoritesRequireExplicitConfirmationBeforeTheyAreMerged()throws Exception{
  ActivityController<MainActivity> controller=Robolectric.buildActivity(MainActivity.class).create().start().resume();MainActivity app=controller.get();app.transferConnectionFactory=url->new Connection(url,"{\"expiresAt\":"+(System.currentTimeMillis()+600000)+",\"status\":\"waiting\"}");
  try{app.repo.favorites.clear();Repo.Stop stop=app.repo.stops.get(0);app.repo.toggleFavorite(stop,"46","A");app.openTransfer("to-watch");java.lang.reflect.Field busy=MainActivity.class.getDeclaredField("transferBusy");busy.setAccessible(true);for(int i=0;i<100&&busy.getBoolean(app);i++){Thread.sleep(10);org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();}assertFalse(busy.getBoolean(app));
   JSONArray rows=new JSONArray().put(new JSONObject().put("stopId",stop.id).put("route","49").put("towards","B"));app.transferPreview=TransferManager.preview(new JSONObject().put("format","foama-favorites-v1").put("favorites",rows),app.repo);app.renderContent();assertTrue(keepsScreenOn(app));assertEquals(1,app.repo.favorites.size());click(app,"Favoriten übernehmen");assertTrue(keepsScreenOn(app));assertEquals(2,app.repo.favorites.size());assertEquals("46",app.repo.favorites.get(0).route);
   for(int i=0;i<100&&busy.getBoolean(app);i++){Thread.sleep(10);org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();}assertTrue(app.transfer.closed);assertFalse(keepsScreenOn(app));assertFalse(app.isFinishing());assertTrue(find(app.getWindow().getDecorView(),"Favoriten übernommen. Transferinhalt gelöscht.")!=null);
  }finally{controller.pause().stop().destroy();}
 }
 private TextView find(View v,String label){if(v instanceof TextView&&((TextView)v).getText().toString().equals(label))return (TextView)v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){TextView t=find(g.getChildAt(i),label);if(t!=null)return t;}}return null;}
 private void click(MainActivity app,String label){View v=find(app.getWindow().getDecorView(),label);assertNotNull(label,v);while(!v.isClickable()&&v.getParent() instanceof View)v=(View)v.getParent();v.performClick();}
 private boolean keepsScreenOn(MainActivity app){return (app.getWindow().getAttributes().flags&WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON)!=0;}
 private void awaitTransfer(MainActivity app)throws Exception {java.lang.reflect.Field busy=MainActivity.class.getDeclaredField("transferBusy");busy.setAccessible(true);for(int i=0;i<200&&busy.getBoolean(app);i++){Thread.sleep(10);org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();}assertFalse("Transfer request finished",busy.getBoolean(app));}
 @Test public void bothDirectionsKeepQrScreenAwakeAndBackRestoresNormalTimeout()throws Exception {
  ActivityController<MainActivity> controller=Robolectric.buildActivity(MainActivity.class).create().start().resume();MainActivity app=controller.get();app.transferConnectionFactory=url->new Connection(url,"{\"expiresAt\":"+(System.currentTimeMillis()+600000)+",\"status\":\"waiting\"}");
  try{app.repo.favorites.clear();app.repo.toggleFavorite(app.repo.stops.get(0),"46","A");assertFalse(keepsScreenOn(app));for(String direction:new String[]{"to-watch","to-phone"}){
   app.openTransfer(direction);assertTrue("Preparing transfer stays awake",keepsScreenOn(app));awaitTransfer(app);assertNotNull(find(app.getWindow().getDecorView(),"Display bleibt während der Übertragung an."));
   org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idleFor(java.time.Duration.ofSeconds(90));awaitTransfer(app);assertEquals("transfer",app.screen);assertTrue(app.active);assertTrue(keepsScreenOn(app));assertFalse(app.isFinishing());
   TransferManager manager=app.transfer;app.onBackPressed();assertFalse(keepsScreenOn(app));assertTrue(manager.closed);assertEquals("more",app.screen);
  }}finally{controller.pause().stop().destroy();}
 }
 @Test public void sendingCompletionReleasesScreenWithoutClosingTheApp()throws Exception {
  ActivityController<MainActivity> controller=Robolectric.buildActivity(MainActivity.class).create().start().resume();MainActivity app=controller.get();app.transferConnectionFactory=url->new Connection(url,"{\"expiresAt\":"+(System.currentTimeMillis()+600000)+",\"status\":\"done\"}");
  try{app.repo.favorites.clear();app.repo.toggleFavorite(app.repo.stops.get(0),"46","A");app.openTransfer("to-phone");awaitTransfer(app);assertTrue(keepsScreenOn(app));click(app,"Übernahme prüfen");awaitTransfer(app);assertTrue(app.transfer.closed);assertFalse(keepsScreenOn(app));assertEquals("transfer",app.screen);assertFalse(app.isFinishing());assertNotNull(find(app.getWindow().getDecorView(),"Übertragung abgeschlossen."));}finally{controller.pause().stop().destroy();}
 }
 @Test public void pendingConfirmationExpiresWithoutAnotherPollAndCannotImportAfterExpiry()throws Exception {
  ActivityController<MainActivity> controller=Robolectric.buildActivity(MainActivity.class).create().start().resume();MainActivity app=controller.get();app.transferConnectionFactory=url->new Connection(url,"{\"expiresAt\":"+(System.currentTimeMillis()+600000)+",\"status\":\"waiting\"}");
  try{app.repo.favorites.clear();Repo.Stop stop=app.repo.stops.get(0);app.openTransfer("to-watch");awaitTransfer(app);JSONArray rows=new JSONArray().put(new JSONObject().put("stopId",stop.id));app.transferPreview=TransferManager.preview(new JSONObject().put("format","foama-favorites-v1").put("favorites",rows),app.repo);app.renderContent();assertTrue(keepsScreenOn(app));
   org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idleFor(java.time.Duration.ofMinutes(10));assertTrue(app.transfer.closed);assertFalse(keepsScreenOn(app));assertNull(app.transferPreview);assertTrue(app.repo.favorites.isEmpty());assertFalse(app.isFinishing());assertNotNull(find(app.getWindow().getDecorView(),"Code abgelaufen. Zurück und neuen Code öffnen."));app.confirmTransfer();assertTrue(app.repo.favorites.isEmpty());
  }finally{controller.pause().stop().destroy();}
 }
 @Test public void terminalPreparationFailureReleasesScreenAndDestroysKeys()throws Exception {
  ActivityController<MainActivity> controller=Robolectric.buildActivity(MainActivity.class).create().start().resume();MainActivity app=controller.get();app.transferConnectionFactory=url->new Connection(url,"invalid-json");
  try{app.openTransfer("to-watch");assertTrue(keepsScreenOn(app));awaitTransfer(app);assertFalse(keepsScreenOn(app));assertTrue(app.transfer.closed);for(byte value:app.transfer.secret)assertEquals(0,value);assertFalse(app.isFinishing());assertNotNull(find(app.getWindow().getDecorView(),"Transfer nicht erreichbar. Zurück und erneut versuchen."));}finally{controller.pause().stop().destroy();}
 }
 @Test public void actualMenuOpensTransferAndBackOrPauseDestroysKeysWithoutChangingFavorites()throws Exception{
  ActivityController<MainActivity> controller=Robolectric.buildActivity(MainActivity.class).create().start().resume();MainActivity app=controller.get();app.transferConnectionFactory=url->new Connection(url,"{\"expiresAt\":"+(System.currentTimeMillis()+600000)+",\"status\":\"waiting\"}");int before=app.repo.favorites.size();
  try{click(app,"Mehr");click(app,"Favoriten");click(app,"Mit Handy übertragen");click(app,"Vom Handy empfangen");assertEquals("transfer",app.screen);TransferManager manager=app.transfer;assertNotNull(manager);assertTrue(keepsScreenOn(app));app.onBackPressed();assertEquals("more",app.screen);assertFalse(keepsScreenOn(app));assertNull(app.transfer);assertTrue(manager.closed);assertNotNull(find(app.getWindow().getDecorView(),"Vom Handy empfangen"));click(app,"Vom Handy empfangen");TransferManager second=app.transfer;controller.pause();assertTrue(second.closed);assertFalse(keepsScreenOn(app));assertNull(app.transfer);assertFalse(app.active);assertEquals(before,app.repo.favorites.size());}finally{controller.stop().destroy();}
 }
}
